#!/usr/bin/env bash
# Generated by OrgCraft 0.22.0. Do not edit: fixes go upstream, settings go in .agent-team/config.sh.
# Reports what this thread is doing to the team board.
#
#   team-status.sh <role>[#instance] <kind> [<status>|-] [--task "..."] [--issue N] [--pr N] [--branch b]
#                  [--commit sha] [--platform p] [--to role] [--severity 1-4] [--evidence path,path] [--team-version sha]
#                  [--detail "..."] [--session id]
#
#   kind    status | handoff | bug | signoff | blocked | note | heartbeat
#   status  idle | working | waiting | blocked | review | done   (required for kind=status; others keep the last one)
#
#   team-status.sh backend-dev status working --task "Invoices API" --issue 42
#   team-status.sh backend-dev handoff waiting --to backend-tester --task "Invoices API" --pr 57
#   team-status.sh qa-web bug - --to web-dev --severity 2 --evidence shots/a.png --detail "Save does nothing"
#   team-status.sh code-reviewer#57 status done
#   team-status.sh status working --task "Invoices API"     the role from AGENT_TEAM_ROLE (env or .agent-team/local.env)
#
# Every report is appended to $AGENT_TEAM_HOME/<project>/events.jsonl (by default ~/.agent-team/<project>/), a folder
# AGENT_TEAM_HOME can point at one every thread shares (set it in local.env, team.env or config.sh), which team-board.sh and the dashboard
# (dashboard.mjs) read. When TEAM_REPORT_URL is set (environment, .agent-team/config.sh or ~/.agent-team/<project>/team.env)
# the report is also posted there, with TEAM_REPORT_TOKEN as x-team-token when set: a dashboard on another machine
# (http://<host>:4747/api/report) or a hosted board (see board/). TEAM_REPORT_MIRROR_URL and TEAM_REPORT_MIRROR_TOKEN
# send the same report to a second board too. Fills branch and commit from git. Never fails the caller: a bad call,
# a missing tool or a refused report prints one line and exits 0. Without jq it runs report.mjs, which needs only Node.
set -uo pipefail
here="$(cd "$(dirname "$0")" && pwd)"
# Without jq, the Node reporter (same arguments, same event) does the job.
if ! command -v jq >/dev/null 2>&1 && command -v node >/dev/null 2>&1; then
  for r in "$here/report.mjs" "$here/../tools/report.mjs"; do [ -f "$r" ] && exec node "$r" "$@"; done
fi
# shellcheck source=lib.sh
. "$here/lib.sh"
at_init

usage() { sed -n '2,23p' "$0" >&2; exit 0; }
# The role can be left out when AGENT_TEAM_ROLE (environment or .agent-team/local.env) names it.
case "${1:-}" in status|handoff|bug|signoff|blocked|note|heartbeat)
  if [ -n "$AT_ROLE" ]; then set -- "$AT_ROLE" "$@"; else
    echo "team-status: not reported (no role: give one first, or set AGENT_TEAM_ROLE in .agent-team/local.env)" >&2; exit 0
  fi ;;
esac
[ $# -ge 2 ] || usage
agent="$1"; kind="$2"; shift 2
status=""
case "${1:-}" in
  ""|--*) ;;
  -) shift ;;
  *) status="$1"; shift ;;
esac
role="${agent%%#*}"
instance=""; [ "$agent" != "$role" ] && instance="${agent#*#}"

case "$kind" in status|handoff|bug|signoff|blocked|note|heartbeat) ;; *)
  echo "team-status: not reported (kind must be status, handoff, bug, signoff, blocked, note or heartbeat)" >&2; exit 0 ;;
esac
case "$status" in ""|idle|working|waiting|blocked|review|done) ;; *)
  echo "team-status: not reported (status must be idle, working, waiting, blocked, review or done)" >&2; exit 0 ;;
esac
if [ "$kind" = status ] && [ -z "$status" ]; then
  echo "team-status: not reported (a status report needs a status)" >&2; exit 0
fi

task=""; issue=""; pr=""; branch=""; commit=""; platform=""; to=""; severity=""; evidence=""; detail=""; team_version=""
session="${AGENT_TEAM_SESSION:-}"
while [ $# -gt 0 ]; do
  case "$1" in
    --task) task="${2:-}"; shift 2 ;;
    --issue) issue="${2:-}"; shift 2 ;;
    --pr) pr="${2:-}"; shift 2 ;;
    --branch) branch="${2:-}"; shift 2 ;;
    --commit) commit="${2:-}"; shift 2 ;;
    --team-version) team_version="${2:-}"; shift 2 ;;
    --platform) platform="${2:-}"; shift 2 ;;
    --to) to="${2:-}"; shift 2 ;;
    --severity) severity="${2:-}"; shift 2 ;;
    --evidence) evidence="${2:-}"; shift 2 ;;
    --detail) detail="${2:-}"; shift 2 ;;
    --session) session="${2:-}"; shift 2 ;;
    -h|--help) usage ;;
    *) echo "team-status: unknown option $1" >&2; shift ;;
  esac
done
case "$kind" in handoff|bug|signoff|blocked)
  if [ -z "$to" ]; then echo "team-status: not reported ($kind needs --to <role>)" >&2; exit 0; fi ;;
esac
if [ -z "$branch" ] && git rev-parse --is-inside-work-tree >/dev/null 2>&1; then
  branch="$(git rev-parse --abbrev-ref HEAD 2>/dev/null || true)"; [ "$branch" = "HEAD" ] && branch=""
fi
if [ -z "$commit" ] && git rev-parse --is-inside-work-tree >/dev/null 2>&1; then
  commit="$(git rev-parse --short=12 HEAD 2>/dev/null || true)"
fi
# The team version this checkout runs: the last commit that changed .agent-team (the rollout view after a publish).
if [ -z "$team_version" ] && git rev-parse --is-inside-work-tree >/dev/null 2>&1; then
  team_version="$(git log -1 --first-parent --format=%H -- .agent-team 2>/dev/null | cut -c1-12 || true)"
fi

if ! command -v jq >/dev/null 2>&1; then
  echo "team-status: not reported (jq is not installed)" >&2
  exit 0
fi
at="$(date -u +%Y-%m-%dT%H:%M:%SZ)"
id="$(date -u +%Y%m%d%H%M%S)-$$-${RANDOM}${RANDOM}"
payload=$(jq -nc --arg id "$id" --arg at "$at" --arg role "$role" --arg instance "$instance" --arg kind "$kind" --arg status "$status" \
  --arg task "$task" --arg issue "$issue" --arg pr "$pr" --arg branch "$branch" --arg commit "$commit" \
  --arg platform "$platform" --arg to "$to" --arg severity "$severity" --arg evidence "$evidence" --arg detail "$detail" \
  --arg session "$session" --arg team_version "$team_version" \
  '{id: $id, at: $at, role: $role, instance: $instance, kind: $kind, status: $status, task: $task, issue: $issue, pr: $pr,
    branch: $branch, commit: $commit, platform: $platform, to: $to, severity: $severity,
    evidence: ($evidence | split(",") | map(select(. != ""))), detail: $detail, session: $session, team_version: $team_version,
    source: "team-status.sh"} | with_entries(select(.value != "" and .value != []))')

mkdir -p "$AT_HOME" 2>/dev/null && printf '%s\n' "$payload" >>"$AT_HOME/events.jsonl" 2>/dev/null \
  || echo "team-status: could not write $AT_HOME/events.jsonl" >&2

# post <url> <token> <label>: one POST, one line on stderr when it is refused or not reached.
post() {
  local auth=() response code body
  [ -n "$2" ] && auth=(-H "x-team-token: $2")
  response=$(curl -sS --max-time 15 -w '\n%{http_code}' -X POST "$1" \
    -H "Content-Type: application/json" ${auth[@]+"${auth[@]}"} --data "$payload" 2>&1) || {
    echo "team-status: $3 not reached (network): ${response:0:200}" >&2; return; }
  code="${response##*$'\n'}"
  body="${response%$'\n'*}"
  if [ "$code" != "200" ]; then
    echo "team-status: $3 refused (HTTP $code): $(jq -r '.error // .' <<<"$body" 2>/dev/null | head -c 200)" >&2
  fi
}
# The mirror gets the same report with the same id, so a team can feed a second board (such as the Studio's
# control plane) next to the one it already runs.
[ -n "${TEAM_REPORT_URL:-}" ] && post "$TEAM_REPORT_URL" "${TEAM_REPORT_TOKEN:-}" "hosted board"
[ -n "${TEAM_REPORT_MIRROR_URL:-}" ] && post "$TEAM_REPORT_MIRROR_URL" "${TEAM_REPORT_MIRROR_TOKEN:-}" "mirror board"
echo "team-status: $agent $kind${status:+ $status}${task:+ · $task}"
exit 0
